    return Response.json({ error: "tankId is required" }, { status: 400 });
  }
  const tank = await db.tank.findUnique({ where: { id: tankId } });
  if (!tank) {
    return Response.json({ error: "tank not found" }, { status: 404 });
  }
  const duplicate = await db.feedLog.findFirst({ where: { title: body.title.trim() } });
  if (duplicate) {
    return Response.json({ error: "title already exists" }, { status: 409 });
  }
  const feedLog = await db.feedLog.create({
    data: {
      title: body.title.trim(),
      feedGrams,
      ...(tankId ? { tankId: tankId } : {}),
      status: "draft",
    },
  });
  return Response.json(feedLog, { status: 201 });
}
